package api.publica;
import java.sql.*;import java.util.*;import config.ConexionBD;import servicio.*;import api.publica.JugadorPublicoDTO.*;
public class JugadorPublicoService {private final ConsultaHistorialCompetitivoService historial=new ConsultaHistorialCompetitivoService();private final RankingDeportivoService ranking=new RankingDeportivoService();
 public Perfil buscar(long perfilId){if(perfilId<=0)throw new IllegalArgumentException("El perfil no es valido.");String q="SELECT p.nombre_publico,p.posicion_preferida,p.disponible_para_jugar,p.acepta_invitaciones,c.id categoria_id,c.nombre categoria,c.color_hex,jc.fecha_desde FROM perfiles_jugador p LEFT JOIN jugador_categorias jc ON jc.perfil_jugador_id=p.id AND jc.estado='VIGENTE' LEFT JOIN categorias_deportivas c ON c.id=jc.categoria_deportiva_id WHERE p.id=? AND p.activo=TRUE";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,perfilId);try(ResultSet r=s.executeQuery()){if(!r.next())throw new PerfilPublicoNoEncontradoException();String nombre=r.getString("nombre_publico");long cid=r.getLong("categoria_id");Categoria categoria=r.wasNull()?null:new Categoria(cid,r.getString("categoria"),r.getString("color_hex"),r.getDate("fecha_desde").toLocalDate());var h=historial.consultar(perfilId);Ranking pos=categoria==null?null:ranking.calcular(cid).stream().filter(x->x.perfilId()==perfilId).findFirst().map(x->new Ranking(x.posicion(),x.puntos(),x.partidos(),x.victorias(),x.derrotas(),x.efectividad(),x.diferenciaSets(),x.diferenciaGames())).orElse(null);List<Partido> partidos=h.historial().stream().map(x->new Partido(x.partidoId(),x.resultado(),x.torneo(),x.categoria(),x.fase(),x.companero(),x.rivales(),x.marcador(),x.fecha())).toList();return new Perfil(perfilId,nombre,iniciales(nombre),r.getString("posicion_preferida"),r.getBoolean("disponible_para_jugar"),r.getBoolean("acepta_invitaciones"),categoria,pos,h.partidos(),h.victorias(),h.derrotas(),h.efectividad(),partidos,categorias(c,perfilId));}}catch(SQLException e){throw new RuntimeException("No se pudo cargar el perfil deportivo publico.",e);}}
 private List<MovimientoCategoria> categorias(Connection c,long id)throws SQLException{String q="SELECT cd.nombre,jc.estado,jc.fecha_desde,jc.fecha_hasta FROM jugador_categorias jc JOIN categorias_deportivas cd ON cd.id=jc.categoria_deportiva_id WHERE jc.perfil_jugador_id=? ORDER BY jc.fecha_desde DESC,jc.id DESC";try(PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);try(ResultSet r=s.executeQuery()){List<MovimientoCategoria>x=new ArrayList<>();while(r.next()){java.sql.Date h=r.getDate(4);x.add(new MovimientoCategoria(r.getString(1),r.getString(2),r.getDate(3).toLocalDate(),h==null?null:h.toLocalDate()));}return x;}}}
 private String iniciales(String n){if(n==null||n.isBlank())return "PJ";String[]p=n.trim().split("\s+");return(p[0].substring(0,1)+(p.length>1?p[p.length-1].substring(0,1):"")).toUpperCase();}
 public static class PerfilPublicoNoEncontradoException extends RuntimeException{public PerfilPublicoNoEncontradoException(){super("El perfil deportivo no existe o no esta disponible.");}}
}
